  function unpackTable(packed, prefix, pad) {
    const catIndices = packed.cat_indices;
    const catLists = packed.cat_lists;
    const rows = packed.rows.map((r, i) => {
      const fullRow = [prefix + String(i + 1).padStart(pad, '0'), ...r];
      for (let j = 0; j < catIndices.length; j++) {
        const colIdx = catIndices[j];
        fullRow[colIdx] = catLists[j][fullRow[colIdx]];
      }
      return fullRow;
    });
    return { columns: packed.columns, rows: rows };
  }

  window.SIMER_DATA = {
    administrativos: raw.administrativos,
    docentes: raw.docentes,
    empleadores: raw.empleadores,
    estudiantes: unpackTable(raw.est_packed, 'EST-', 5),
    graduados: unpackTable(raw.grad_packed, 'GRAD-', 5)
  };
